sealed class FxTabDrag {public MasterFx Owner;public int Effect;}
sealed class FxTabButton:PadButton {
 public MasterFx Owner;public int Effect,Slot;public Action<int,int> Reorder;Point down;bool moved,holdCancelled;long pressedAt;
 public FxTabButton(){AllowDrop=true;}
 protected override void OnMouseDown(MouseEventArgs e){down=e.Location;moved=false;holdCancelled=false;pressedAt=System.Diagnostics.Stopwatch.GetTimestamp();base.OnMouseDown(e);}
 protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);if(e.Button==MouseButtons.Left&&!moved&&Owner.Routing==1&&(Math.Abs(e.X-down.X)>6||Math.Abs(e.Y-down.Y)>6)){if((System.Diagnostics.Stopwatch.GetTimestamp()-pressedAt)/(double)System.Diagnostics.Stopwatch.Frequency<1){holdCancelled=true;return;}if(holdCancelled)return;moved=true;DoDragDrop(new FxTabDrag{Owner=Owner,Effect=Effect},DragDropEffects.Move);}}
 protected override void OnClick(EventArgs e){if(!moved&&!holdCancelled)base.OnClick(e);}
 protected override void OnDragOver(DragEventArgs e){var data=e.Data.GetData(typeof(FxTabDrag)) as FxTabDrag;e.Effect=data!=null&&object.ReferenceEquals(data.Owner,Owner)&&Owner.Routing==1?DragDropEffects.Move:DragDropEffects.None;base.OnDragOver(e);}
 protected override void OnDragDrop(DragEventArgs e){var data=e.Data.GetData(typeof(FxTabDrag)) as FxTabDrag;if(data!=null&&object.ReferenceEquals(data.Owner,Owner)&&Owner.Routing==1&&Reorder!=null){int from=Array.IndexOf(FxOrder.Items(Owner.SerialOrder),data.Effect);if(from>=0)Reorder(from,Slot);}base.OnDragDrop(e);}
}
